  const body = new Body({
    kind: 'car', mass: m, inertia: m * (FIXED.carLen ** 2 + 1.2 ** 2) / 12,
    friction: FIXED.carFriction, restitution: FIXED.carRestitution,
    canSleep: false, layer: -1,
    x: -FIXED.runUp - (FIXED.carLen - CAR.com[0]), y: CAR.com[1],
  });
  body.hull = body.addShape(carHullLocal(0));
  // Tyres are not rigid shapes: each wheel rides a sampled terrain profile (road + debris)
  // through its own spring-damper, so it can roll over bricks instead of wedging them.
  // Suspension: 1.5 Hz ride frequency, 30% damping, statically balanced at design ride height.
  const omega = 2 * Math.PI * 1.5;
  const k = (m / 2) * omega * omega;
  const cDamp = 2 * 0.3 * Math.sqrt(k * m / 2);
  const Lrest = CAR.mountY - CAR.wheelR;
  const span = CAR.wheelX[1] - CAR.wheelX[0];
  const loads = [(CAR.wheelX[1] - CAR.com[0]) / span, (CAR.com[0] - CAR.wheelX[0]) / span];
  const wheels = CAR.wheelX.map((wx, i) => {
    const L0 = Lrest + loads[i] * m * cfg.gravity / k;
    return { lx: wx - CAR.com[0], ly: CAR.mountY - CAR.com[1], L0, L: Lrest, contact: true, spin: 0, load: 0, slip: 0 };
  });
  const maxL0 = Math.max(wheels[0].L0, wheels[1].L0);
  body.susp = { k, c: cDamp, R: CAR.wheelR, Lmin: 0.12, Lmax: maxL0 + 0.06, mu: cfg.groundFriction, wheels };
  return body;
}

/* =====================================================================
   5. EXPERIMENT (scene build, drive/tow + brakes, telemetry)
   ===================================================================== */
class Experiment {
  constructor(cfg) {
    this.cfg = Object.freeze({ ...cfg });
    this.world = new World(cfg.gravity, cfg.groundFriction);
    this.car = this.world.add(createCar(cfg));
    this.buildWall();

    this.phase = 'ready';
    this.t = 0;
    this.impactT = null;
    this.impactSpeed = 0;
    this.brakes = false;
    this.accel = Math.max(2.5, cfg.carSpeed * cfg.carSpeed / (2 * FIXED.accelDist));
    this.crushE = 0; this.crush = 0; this.hullCrush = 0;
    this.decel = 0; this.peakDecel = 0; this.vxPrev = 0;
    this.peakWallMomentum = 0; this.wallMomentum = 0;
    this.quietT = 0; this.stepEvents = [];
    this.moving = 0; this.displaced = 0;
    this.result = '';
  }

  buildWall() {
    const { cols, rows, layers, brickMass, brickFriction, brickRestitution } = this.cfg;
    const W = FIXED.brickW, H = FIXED.brickH;
    this.wallX0 = 0;
    this.wallX1 = cols * W;
    this.wallH = rows * H;
    this.bricks = [];
    this.layerBricks = Array.from({ length: layers }, () => []);
    const make = (cx, cy, w, layer, row, col) => {
      const m = brickMass * (w / W);
      const b = new Body({
        kind: 'brick', mass: m, inertia: m * (w * w + H * H) / 12,
        friction: brickFriction, restitution: brickRestitution,
        layer, x: cx, y: cy, awake: false,
      });
      b.addShape([[-w / 2, -H / 2], [w / 2, -H / 2], [w / 2, H / 2], [-w / 2, H / 2]]);
      b.hw = w / 2; b.hh = H / 2;
      b.ix = cx; b.iy = cy;
      b.row = row; b.col = col;
      // deterministic per-brick tint
      const r1 = hash01(layer, row, col), r2 = hash01(col, layer + 7, row), r3 = hash01(row + 3, col, layer);
      const hue = 7 + r1 * 14, sat = 46 + r2 * 16, lig = 38 + r3 * 9 - layer * 4.5;
      b.col0 = `hsl(${hue.toFixed(1)},${sat.toFixed(0)}%,${lig.toFixed(1)}%)`;
      b.colHi = `hsl(${hue.toFixed(1)},${sat.toFixed(0)}%,${(lig + 9).toFixed(1)}%)`;
      b.colSh = `hsl(${hue.toFixed(1)},${(sat - 6).toFixed(0)}%,${(lig - 11).toFixed(1)}%)`;
      this.world.add(b);
      this.bricks.push(b);
      this.layerBricks[layer].push(b);
    };
    for (let L = 0; L < layers; L++) {
      for (let r = 0; r < rows; r++) {
        const y = H / 2 + r * H;
        if ((r + L) % 2 === 0) {
          for (let c = 0; c < cols; c++) make(W / 2 + c * W, y, W, L, r, c);
        } else {
          make(W / 4, y, W / 2, L, r, 0);
          for (let c = 0; c < cols - 1; c++) make(W + c * W, y, W, L, r, c + 1);
          make(cols * W - W / 4, y, W / 2, L, r, cols);
        }
      }
    }
    this.totalBrickMass = this.bricks.reduce((s, b) => s + b.mass, 0);
  }

  start() { this.phase = 'accelerating'; }

  carFrontX() {
    const c = this.car;
    return c.x + Math.cos(c.a) * (FIXED.carLen - CAR.com[0] - this.crush);
  }

  carEnergy() {
    const c = this.car;
    return 0.5 * c.mass * (c.vx * c.vx + c.vy * c.vy) + 0.5 * c.I * c.w * c.w + c.mass * this.cfg.gravity * c.y;
  }

  /** Suspension, tyres, tow cable. Called by the world before velocity integration. */
  applyCarForces() {
    const car = this.car, S = car.susp, cfg = this.cfg;
    const cs = Math.cos(car.a), sn = Math.sin(car.a);
    const upx = -sn, upy = cs;
    this.brakeWork = 0;
    for (const wh of S.wheels) {
      const wx = car.x + cs * wh.lx - sn * wh.ly;
      const wy = car.y + sn * wh.lx + cs * wh.ly;
      let L = S.Lmax, support = null, spx = 0, spy = 0;
      wh.contact = false; wh.load = 0; wh.slip = 0;
      if (upy > 0.3) {
        // required wheel-centre height over the terrain profile (road y=0 plus any debris below the mount)
        const cx = wx + sn * wh.L, R = S.R;
        let need = R;
        spx = cx;
        for (const b of this.bricks) {
          const sh = b.shapes[0];
          if (sh.maxX < cx - R || sh.minX > cx + R || sh.minY > wy - 0.05 || sh.maxY < 0.02) continue;
          for (const f of WHEEL_SAMPLES) {
            const dx = f * R, top = shapeTopAt(sh, cx + dx);
