      const rx = wx - car.x, ry = wy - car.y;
      const vmx = car.vx - car.w * ry, vmy = car.vy + car.w * rx;
      const vAlong = vmx * upx + vmy * upy;
      let F = S.k * (wh.L0 - L) - S.c * vAlong;
      if (L < S.Lmin) F += S.k * 6 * (S.Lmin - L);   // bump stop
      if (F < 0) F = 0;
      car.fx += F * upx; car.fy += F * upy;
      car.tq += rx * F * upy - ry * F * upx;
      const N = F * upy;
      wh.load = N;
      // tyre longitudinal force at the contact patch (road or brick surface)
      const cpx = support ? spx : wx + sn * L, cpy = support ? spy : 0;
      const rcx = cpx - car.x, rcy = cpy - car.y;
      let vcx = car.vx - car.w * rcy;
      if (support) vcx -= support.vx - support.w * (cpy - support.y);
      const mEff = support ? Math.min(car.mass * 0.5, support.mass) : car.mass * 0.5;
