      const V = cfg.carSpeed, roll = 0.015 * car.mass * cfg.gravity;
      const Fmax = car.mass * this.accel + roll;
      const F = clamp(car.mass * (V - car.vx) * INV_DT + roll, 0, Fmax);
      car.fx += F;
    }
  }

  stepOnce() {
    if (this.phase === 'ready' || this.phase === 'settled') return;
    const car = this.car, w = this.world;
    // crumple zone reshapes the collision hull (only ever shortens -> never creates overlap)
    if (this.crush - this.hullCrush > 0.012) {
      this.hullCrush = this.crush;
      car.hull.setVerts(carHullLocal(this.hullCrush));
      car.update();
    }
    const e0 = this.carEnergy();
    w.step(() => this.applyCarForces());
    this.t += DT;

