const fs = require('fs');
const html = fs.readFileSync(__dirname + '/index.html', 'utf8');
let js = html.match(/<script>([\s\S]*)<\/script>/)[1];
js = js.replace('window.__crashLab = {', 'window.__E = Experiment; window.__crashLab = {');
const el = () => new Proxy(function () {}, {
  get: (t, k) => k === 'classList' ? { toggle: () => false, add() {}, remove() {} }
    : k === 'getContext' ? () => new Proxy({}, { get: () => () => ({ addColorStop() {} }) })
    : k === 'getBoundingClientRect' ? () => ({ width: 1200, height: 700 })
    : k === 'querySelector' ? () => el() : k === 'style' ? {} : (t[k] ?? el()),
  set: (t, k, v) => { t[k] = v; return true; }, apply: () => el(),
});
global.document = { getElementById: () => el(), createElement: () => el() };
global.window = { devicePixelRatio: 1, innerWidth: 1400, addEventListener() {} };
global.ResizeObserver = class { observe() {} };
global.requestAnimationFrame = () => {};
global.performance = { now: () => 0 };
eval(js);

const mode = process.argv[2] || 'suite';
const DEF = { carSpeed: 22, cols: 12, rows: 8, layers: 2, brickMass: 2.5, gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18, carMass: 1250, groundFriction: 0.85, scale: 80 };

if (mode === 'suite') {
  const cases = [{}, {}, { carSpeed: 5, brickMass: 12 }, { carSpeed: 5 }, { carSpeed: 10 }, { brickMass: 12 }, { carSpeed: 45 }, { layers: 5 }, { carSpeed: 45, cols: 24, rows: 16, layers: 5 }, { carSpeed: 10, rows: 3, cols: 4, layers: 1, brickMass: 0.5 }];
  for (const c of cases) {
    const t = Date.now();
    const e = new window.__E({ ...DEF, ...c }); e.start();
    let maxBV = 0, maxA = 0;
    for (let i = 0; i < 240 * 25 && e.phase !== 'settled'; i++) {
      e.stepOnce();
      for (const b of e.bricks) { const v = Math.hypot(b.vx, b.vy); if (v > maxBV) maxBV = v; }
      maxA = Math.max(maxA, Math.abs(e.car.a));
    }
    e.countDisplaced();
    console.log(JSON.stringify(c), e.phase, 't', e.t.toFixed(2), 'imp', e.impactSpeed.toFixed(2), 'carX', e.car.x.toFixed(2), 'carA', e.car.a.toFixed(2), 'maxCarA', maxA.toFixed(2), 'maxBrickV', maxBV.toFixed(1), 'disp', e.displaced + '/' + e.bricks.length, e.result, (Date.now() - t) + 'ms');
  }
} else if (mode === 'det') {
  const a = JSON.stringify(window.__crashLab.simulate({}, 10));
  const b = JSON.stringify(window.__crashLab.simulate({}, 10));
  console.log(a); console.log(a === b ? 'DETERMINISTIC' : 'MISMATCH ' + b);
}

