require('./_harness.cjs');
const DEF = { carSpeed: 10, cols: 4, rows: 3, layers: 1, brickMass: 0.5, gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18, carMass: 1250, groundFriction: 0.85, scale: 80 };
