    console.log(e.t.toFixed(3), 'b0', b.x.toFixed(2), b.y.toFixed(2), b.a.toFixed(2), 'v', b.vx.toFixed(1), b.vy.toFixed(1), b.w.toFixed(1), 'car', car.x.toFixed(2), 'front', e.carFrontX().toFixed(2), 'wh', car.susp.wheels.map(w => w.L.toFixed(2) + (w.contact ? 'c' : '')).join(','), arbs);
  }
}
EOF
