const fs = require('fs');
const html = fs.readFileSync(__dirname + '/index.html', 'utf8');
let js = html.match(/<script>([\s\S]*)<\/script>/)[1];
js = js.replace('window.__crashLab = {', 'window.__E = Experiment; window.__crashLab = {');
if (process.env.NODEBRIS) js = js.replace('for (const b of this.bricks) {\n          const sh = b.shapes[0];', 'for (const b of []) {\n          const sh = b.shapes[0];');
if (process.env.HOOK) {
  js = js.replace('    for (let it = 0; it < RELAX_ITERS; it++)', "    globalThis.__hook && __hook('integrated', this);\n    for (let it = 0; it < RELAX_ITERS; it++)");
  js = js.replace('    for (let i = 0; i < act.length; i++) applyRestitution(act[i]);', "    globalThis.__hook && __hook('relaxed', this);\n    for (let i = 0; i < act.length; i++) applyRestitution(act[i]);\n    globalThis.__hook && __hook('restituted', this);");
  js = js.replace('    for (let i = 0; i < act.length; i++) prestep(act[i]);', "    globalThis.__hook && __hook('pre', this);\n    for (let i = 0; i < act.length; i++) prestep(act[i]);\n    globalThis.__hook && __hook('warm', this);");
}
const el = () => new Proxy(function () {}, {
  get: (t, k) => k === 'classList' ? { toggle: () => false, add() {}, remove() {} }
    : k === 'getContext' ? () => new Proxy({}, { get: () => () => ({ addColorStop() {} }) })
    : k === 'getBoundingClientRect' ? () => ({ width: 1200, height: 700 })
    : k === 'querySelector' ? () => el() : k === 'style' ? {} : (t[k] ?? el()),
  set: (t, k, v) => { t[k] = v; return true; }, apply: () => el(),
});
global.document = { getElementById: () => el(), createElement: () => el() };
global.window = { devicePixelRatio: 1, innerWidth: 1400, addEventListener() {} };
global.ResizeObserver = class { observe() {} };
global.requestAnimationFrame = () => {};
global.performance = { now: () => 0 };
eval(js);

const mode = process.argv[2] || 'suite';
const DEF = { carSpeed: 22, cols: 12, rows: 8, layers: 2, brickMass: 2.5, gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18, carMass: 1250, groundFriction: 0.85, scale: 80 };

if (mode === 'suite') {
  const cases = [{}, {}, { carSpeed: 5, brickMass: 12 }, { carSpeed: 5 }, { carSpeed: 10 }, { brickMass: 12 }, { carSpeed: 45 }, { layers: 5 }, { carSpeed: 10, rows: 3, cols: 4, layers: 1, brickMass: 0.5 }, { carSpeed: 45, brickMass: 0.5, rows: 16 }];
  if (process.argv[3] === 'full') cases.push({ carSpeed: 45, cols: 24, rows: 16, layers: 5 }, { carSpeed: 5, cols: 24, rows: 16, layers: 5, brickMass: 12 });
  for (const c of cases) {
    const t = Date.now();
    const e = new window.__E({ ...DEF, ...c }); e.start();
    let maxBV = 0, maxA = 0;
    for (let i = 0; i < 240 * 25 && e.phase !== 'settled'; i++) {
      e.stepOnce();
      for (const b of e.bricks) { const v = Math.hypot(b.vx, b.vy); if (v > maxBV) maxBV = v; }
      maxA = Math.max(maxA, Math.abs(e.car.a));
    }
    e.countDisplaced();
    console.log(JSON.stringify(c), e.phase, 't', e.t.toFixed(2), 'imp', e.impactSpeed.toFixed(2), 'carX', e.car.x.toFixed(2), 'carA', e.car.a.toFixed(2), 'maxCarA', maxA.toFixed(2), 'maxBrickV', maxBV.toFixed(1), 'disp', e.displaced + '/' + e.bricks.length, e.result, (Date.now() - t) + 'ms');
  }
} else if (mode === 'spike') {
  const e = new window.__E({ ...DEF, ...JSON.parse(process.argv[3] || '{}') }); e.start();
  let n = 0;
  for (let i = 0; i < 240 * 12 && n < 10; i++) {
    const prev = e.bricks.map(b => [b.vx, b.vy, b.w]);
    const cs = e.car.susp.wheels.map(w => w.load.toFixed(0));
    e.stepOnce();
    e.bricks.forEach((b, k) => {
      const dv = Math.hypot(b.vx - prev[k][0], b.vy - prev[k][1]);
      if (dv > 12 && n < 10) {
        n++;
        console.log(e.t.toFixed(3), 'brick', k, 'pos', b.x.toFixed(2), b.y.toFixed(2), 'a', b.a.toFixed(2), 'v', prev[k].map(q => q.toFixed(1)).join(','), '->', [b.vx, b.vy, b.w].map(q => q.toFixed(1)).join(','),
          'car', e.car.x.toFixed(2), e.car.y.toFixed(2), e.car.a.toFixed(2), 'wheelLoads', cs.join('/'));
        for (const a of e.world.active) if (a.A === b || a.B === b) {
          const o = a.A === b ? a.B : a.A;
          console.log('    ', o.kind + (o.kind === 'brick' ? '#' + e.bricks.indexOf(o) : ''), 'sh', a.sA.id, a.sB.id, 'n', a.nx.toFixed(2), a.ny.toFixed(2), 'sep', a.cs.slice(0, a.n).map(c => c.sep.toFixed(3)).join('/'), 'Pn', a.cs.slice(0, a.n).map(c => c.Pn.toFixed(1)).join('/'), 'Pt', a.cs.slice(0, a.n).map(c => c.Pt.toFixed(1)).join('/'));
        }
      }
    });
  }
} else if (mode === 'trace') {
  const e = new window.__E({ ...DEF, ...JSON.parse(process.argv[3] || '{}') }); e.start();
  for (let i = 0; i < 240 * (+process.argv[4] || 6); i++) {
    e.stepOnce();
    if (e.impactT !== null && i % 12 === 0) {
      const c = e.car;
      console.log(e.t.toFixed(3), e.phase, 'x', c.x.toFixed(2), 'y', c.y.toFixed(2), 'a', c.a.toFixed(2), 'vx', c.vx.toFixed(2), 'vy', c.vy.toFixed(2), 'w', c.w.toFixed(2), 'L', c.susp.wheels.map(w => w.L.toFixed(2) + (w.contact ? 'c' : '') + ':' + w.load.toFixed(0)).join(','));
    }
  }
} else if (mode === 'det') {
  const a = JSON.stringify(window.__crashLab.simulate({}, 10));
  const b = JSON.stringify(window.__crashLab.simulate({}, 10));
  console.log(a); console.log(a === b ? 'DETERMINISTIC' : 'MISMATCH ' + b);
}

